if __name__ == "__main__":
    import config

    for title, group in (("human", HUMAN_TEXTS), ("AI", AI_TEXTS)):
        print(f"{title} texts")
        for tid, text in group:
            n = len(text.split())
            ok = "ok" if config.MIN_WORDS <= n <= config.MAX_WORDS else "OUTSIDE 45-300"
            print(f"  {tid}  {n:>3} words  {ok}")
